@SuppressWarnings("unchecked") // Casts guarded by conditionals.
static TypeAdapter<?> getTypeAdapter(ConstructorConstructor constructorConstructor, Gson gson,
    TypeToken<?> fieldType, JsonAdapter annotation) {
  Class<?> value = annotation.value();
  final TypeAdapter<?> typeAdapter;
  if (TypeAdapter.class.isAssignableFrom(value)) {
    Class<TypeAdapter<?>> typeAdapterClass = (Class<TypeAdapter<?>>) value;
    typeAdapter = constructorConstructor.get(TypeToken.get(typeAdapterClass)).construct();
    if (typeAdapter == null) {
      throw new IllegalArgumentException("Failed to construct TypeAdapter for " + value.getName());
    }
  } else if (TypeAdapterFactory.class.isAssignableFrom(value)) {
    Class<TypeAdapterFactory> typeAdapterFactory = (Class<TypeAdapterFactory>) value;
    TypeAdapterFactory factory = constructorConstructor.get(TypeToken.get(typeAdapterFactory)).construct();
    if (factory == null) {
      throw new IllegalArgumentException("Failed to construct TypeAdapterFactory for " + value.getName());
    }
    typeAdapter = factory.create(gson, fieldType);
    if (typeAdapter == null) {
      throw new IllegalArgumentException("TypeAdapterFactory " + value.getName() + " failed to create a TypeAdapter for " + fieldType);
    }
  } else {
    throw new IllegalArgumentException(
        "@JsonAdapter value must be TypeAdapter or TypeAdapterFactory reference.");
  }

  return typeAdapter.nullSafe();
}

